using System.Collections.Generic;using System.Text;public class Solution{public string RearrangeString(string s,int k){if(k<=1)return s;int[]c=new int[26];foreach(char x in s)c[x-'a']++;var pq=new PriorityQueue<(int cnt,int ch),(int neg,int ch)>();for(int i=0;i<26;i++)if(c[i]>0)pq.Enqueue((c[i],i),(-c[i],i));var q=new Queue<(int release,int cnt,int ch)>();var o=new StringBuilder();for(int pos=0;pos<s.Length;pos++){while(q.Count>0&&q.Peek().release<=pos){var x=q.Dequeue();pq.Enqueue((x.cnt,x.ch),(-x.cnt,x.ch));}if(pq.Count==0)return"";var x=pq.Dequeue();o.Append((char)('a'+x.ch));x.cnt--;if(x.cnt>0)q.Enqueue((pos+k,x.cnt,x.ch));}return o.ToString();}}
